const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename it would apply
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

function getMigrationFiles() {
  try {
    const files = fs.readdirSync(MIGRATIONS_DIR, { withFileTypes: true });

    // Filter for .sql files and sort them alphabetically
    const sqlFiles = files
      .filter(dirent => 
        dirent.isFile() && 
        dirent.name.endsWith('.sql')
      )
      .map(dirent => dirent.name)
      .sort();

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    return [];
  }
}

function applyMigrations() {
  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found in ./migrations/');
    return;
  }

  console.log('Starting database migrations...');
  console.log('');

  for (const file of migrationFiles) {
    console.log(`Would apply: ${file}`);
  }

  console.log('');
  console.log(`Total migrations to apply: ${migrationFiles.length}`);
}

// Run the migration script
applyMigrations();

