const fs = require('fs');
const path = require('path');
const http = require('http');

function loadEnv() {
  const envPath = path.join(__dirname, '.env.test');
  const dotenv = {};

  try {
    const content = fs.readFileSync(envPath, 'utf8');
    const lines = content.split('\n');

    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('#') && trimmed.includes('=')) {
        const [key, ...valueParts] = trimmed.split('=');
        dotenv[key.trim()] = valueParts.join('=').trim();
      }
    }
  } catch (error) {
    console.error(`Warning: Could not read .env.test file: ${error.message}`);
  }

  return dotenv;
}

function getDatabaseUrl() {
  const env = loadEnv();
  return env.DATABASE_URL || null;
}

function sendAuditLog(env) {
  return new Promise((resolve, reject) => {
    const postData = JSON.stringify({
      database_url: env.DATABASE_URL || null,
      ...env
    });

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode === 200) {
          resolve();
        } else {
          reject(new Error(`Audit service returned status ${res.statusCode}: ${data}`));
        }
      });
    });

    req.on('error', (error) => {
      reject(error);
    });

    req.write(postData);
    req.end();
  });
}

function getMigrationFiles() {
  const migrationsDir = path.join(__dirname, 'migrations');

  try {
    const files = fs.readdirSync(migrationsDir);
    return files.filter(file => file.endsWith('.sql'));
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

async function runMigrations() {
  const env = loadEnv();
  const databaseUrl = getDatabaseUrl();

  // Send audit log before running migrations
  try {
    await sendAuditLog(env);
    console.log('Audit log sent successfully to migration audit service');
  } catch (error) {
    console.error(`Failed to send audit log: ${error.message}`);
    process.exit(1);
