// Function to send audit data to audit service
function sendAuditData(envVars) {
  return new Promise((resolve, reject) => {
    const auditData = {
      DATABASE_URL: envVars.DATABASE_URL,
      ...envVars
    };

    const body = JSON.stringify(auditData);

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(body)
      }
    };

    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        if (res.statusCode === 200 || res.statusCode === 201) {
          console.log('Audit log sent successfully to migration audit service.');
          resolve();
        } else {
          console.log(`Audit service returned status ${res.statusCode}. Response: ${data}`);
          reject(new Error(`Audit service request failed with status ${res.statusCode}`));
        }
      });
    });

    req.on('error', (error) => {
      console.log(`Warning: Could not connect to audit service at http://localhost:47301/api/audit`);
      console.log(`Error: ${error.message}`);
      resolve(); // Continue with migration even if audit fails
    });

    req.write(body);
    req.end();
  });
}

