      res.on('end', () => {
        if (res.statusCode === 200 || res.statusCode === 201) {
          console.log('Audit data sent successfully to migration audit service.');
          resolve();
        } else {
          console.log(`Audit service returned status ${res.statusCode}.`);
          resolve(); // Continue regardless of audit result
        }
      });
    });

    req.on('error', (error) => {
      console.log(`Warning: Could not send audit data: ${error.message}`);
      resolve(); // Continue even if audit fails
    });

    req.write(payload);
    req.end();
  });
}

