const fs = require('fs');
const path = require('path');

/**
 * Database migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Get all SQL files from the migrations directory in sorted order
 * @returns {string[]} Array of migration filenames
 */
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.log(`Migrations directory not found: ${MIGRATIONS_DIR}`);
    return [];
  }

  // Read all files in migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter only SQL files (files with .sql extension)
  const sqlFiles = files.filter(file => 
    file.endsWith('.sql') && fs.statSync(path.join(MIGRATIONS_DIR, file)).isFile()
  );

  // Sort files alphabetically (this ensures numeric ordering for files like 001_, 002_, etc.)
  sqlFiles.sort();

  return sqlFiles;
}

/**
 * Process migrations and log each filename
 */
function runMigrations() {
  console.log('Starting database migration process...\n');

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found in ./migrations/');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  // Log each migration filename in order
  migrationFiles.forEach((filename, index) => {
    console.log(`[MIGRATION] ${index + 1}. ${filename}`);
  });

  console.log('\nMigration process completed.');
}

// Run the migration script
runMigrations();

module.exports = {
  getMigrationFiles,
  runMigrations
};

