/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

function runMigrations() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.log('Migrations directory not found:', MIGRATIONS_DIR);
    return;
  }

  // Get all SQL files from the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR)
    .filter(file => file.endsWith('.sql'))
    .sort(); // Sort alphabetically for consistent ordering

  if (files.length === 0) {
    console.log('No SQL migration files found in', MIGRATIONS_DIR);
    return;
  }

  console.log('Found migration files:');
  files.forEach(file => {
    console.log(`- ${file}`);
  });

  // Log which files would be applied
  console.log('\nMigration files to apply (in order):');
  files.forEach(file => {
    console.log(file);
  });
}

// Run the migration script
runMigrations();

