#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Get all SQL files from the migrations directory
 * @returns {string[]} Array of migration filenames sorted alphabetically
 */
function getMigrationFiles() {
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.log('Migrations directory not found');
    return [];
  }

  const files = fs.readdirSync(MIGRATIONS_DIR);
  const sqlFiles = files
    .filter(file => file.endsWith('.sql'))
    .sort(); // Sort alphabetically to ensure consistent order

  return sqlFiles;
}

/**
 * Log each migration file that would be applied
 */
function logMigrationsToApply() {
  const migrations = getMigrationFiles();

  if (migrations.length === 0) {
    console.log('No migrations found in ./migrations/ directory');
    return;
  }

  console.log('Found migrations to apply:');
  migrations.forEach((migration, index) => {
    console.log(`${index + 1}. ${migration}`);
  });
}

// Run the migration logger
logMigrationsToApply();

